+package com.example.contact;
+
+import java.time.Instant;
+import java.time.ZoneId;
+import java.time.format.DateTimeFormatter;
+import java.time.format.FormatStyle;
+import java.util.regex.Pattern;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final DateTimeFormatter SENT_FORMAT = DateTimeFormatter
+            .ofLocalizedDateTime(FormatStyle.SHORT).withZone(ZoneId.systemDefault());
+
+    private final MessageService messages;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>();
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    public ContactView(MessageService messages) {
+        this.messages = messages;
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(e -> send.setEnabled(true));
+        email.addValueChangeListener(e -> send.setEnabled(true));
+        phone.addValueChangeListener(e -> send.setEnabled(true));
+        message.addValueChangeListener(e -> send.setEnabled(true));
+
+        send.addClickListener(e -> sendMessage());
+        // Enter sends; Shift+Enter still gives a line break in the message.
+        Shortcuts.addShortcutListener(this, () -> {
+            if (send.isEnabled()) {
+                sendMessage();
+            }
+        }, Key.ENTER).setBrowserDefaultAllowed(false);
+
+        message.setWidthFull();
+
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.addColumn(m -> SENT_FORMAT.format(m.sentAt())).setHeader("Sent").setAutoWidth(true);
+        grid.setItems(messages.findAll());
+
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add("The contact form has unsent input.");
+        leaveDialog.getFooter().add(
+                new Button("Keep editing", e -> leaveDialog.close()),
+                new Button("Discard", e -> {
+                    leaveDialog.close();
+                    if (pendingNavigation != null) {
+                        pendingNavigation.proceed();
+                        pendingNavigation = null;
+                    }
+                }));
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class),
+                name, email, phone, message, send, grid, leaveDialog);
+    }
+
+    private void sendMessage() {
+        clearInvalid();
+        String senderName = name.getValue().trim();
+        String senderEmail = email.getValue().trim();
+        String senderPhone = phone.getValue().trim();
+        String text = message.getValue().trim();
+
+        if (senderName.isBlank()) {
+            markInvalid(name, "Name is required");
+        }
+        if (!senderEmail.isBlank() && !EMAIL.matcher(senderEmail).matches()) {
+            markInvalid(email, "Enter a valid e-mail address");
+        } else if (senderEmail.isBlank() && senderPhone.isBlank()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+        }
+        if (text.isBlank()) {
+            markInvalid(message, "Message is required");
+        } else if (text.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, "Message must be at most 500 characters");
+        }
+        if (name.isInvalid() || email.isInvalid() || message.isInvalid()) {
+            return;
+        }
+
+        messages.add(new ContactMessage(senderName, senderEmail, senderPhone, text, Instant.now()));
+        grid.setItems(messages.findAll());
+        Notification.show("Message sent");
+
+        // Clearing the fields fires value change events that re-enable Send,
+        // so disable it afterwards.
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+    }
+
+    private void clearInvalid() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private void markInvalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private boolean hasUnsentInput() {
+        return !name.getValue().isBlank() || !email.getValue().isBlank()
+                || !phone.getValue().isBlank() || !message.getValue().isBlank();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsentInput()) {
+            return;
+        }
+        event.postpone();
+        pendingNavigation = event.getContinueNavigationAction();
+        leaveDialog.open();
+    }
+}
